import React from 'react'
import { useParams, Link } from 'react-router-dom'
import { Helmet } from 'react-helmet'
import { blogDetails } from '../../portfolio'
import './BlogDetail.css'

function BlogDetail() {
  const { id } = useParams()
  const blog = blogDetails[id]

  if (!blog) {
    return (
      <div className='blog-not-found'>
        <Helmet>
          <title>Blog Not Found | My Blog</title>
          <meta name='robots' content='noindex' />
        </Helmet>
        <h2>Blog Not Found</h2>
        <p>
          We couldn’t find the blog you’re looking for. Please check the URL or
          go back to the blogs page.
        </p>
        <br />
        <Link to='/blogs'>
          <span type='button' className='btn btn--outline'>
            Back to Blogs
          </span>
        </Link>
      </div>
    )
  }

  const descriptionText =
    blog.excerpt || blog.description?.replace(/<[^>]+>/g, '').slice(0, 160)

  return (
    <article className='blog-detail'>
      <Helmet>
        <title>
          {blog.title} | By {blog.author || 'Harsh'}
        </title>
        <meta name='description' content={descriptionText} />
        <meta property='og:title' content={blog.title} />
        <meta property='og:description' content={descriptionText} />
        <meta property='og:image' content={blog.headerImage} />
        <meta property='og:type' content='article' />
        <meta name='twitter:card' content='summary_large_image' />

        <script type='application/ld+json'>
          {JSON.stringify({
            '@context': 'https://schema.org',
            '@type': 'BlogPosting',
            mainEntityOfPage: {
              '@type': 'WebPage',
              '@id': `https://harsh-chhantbar.github.io/blogs/${id}`,
            },
            headline: blog.title,
            image: blog.headerImage,
            author: {
              '@type': 'Person',
              name: blog.author || 'Harsh Chhantbar',
            },
            publisher: {
              '@type': 'Organization',
              name: 'Harsh Chhantbar',
              logo: {
                '@type': 'ImageObject',
                url: 'https://harsh-chhantbar.github.io/favicon.ico',
              },
            },
            description: descriptionText,
            articleBody: blog.description?.replace(/<[^>]+>/g, ''),
          })}
        </script>
      </Helmet>

      <header>
        <Link to='/blogs'>
          <span type='button' className='btn btn--outline'>
            Back to Blogs
          </span>
        </Link>
        <h1>{blog.title}</h1>

        {blog.headerImage && (
          <img
            src={blog.headerImage}
            alt={`${blog.title} - header`}
            className='blog-header-image'
            loading='lazy'
          />
        )}

        {blog.date && (
          <time dateTime={blog.date}>
            {new Date(blog.date).toLocaleDateString()}
          </time>
        )}
      </header>

      <section
        className='blog-content'
        dangerouslySetInnerHTML={{ __html: blog.description }}
      />
    </article>
  )
}

export default BlogDetail
