import { useState } from 'react'
import uniqid from 'uniqid'
import { projects } from '../../portfolio'
import './Projects.css'

const Projects = () => {
  if (!projects.length) return null

  // Get all unique companies
  const companies = [...new Set(projects.map((p) => p.company))]

  // Active tab state
  const [activeCompany, setActiveCompany] = useState(companies[0])

  // Filter projects by selected company
  const filteredProjects = projects.filter((p) => p.company === activeCompany)

  return (
    <section id='projects' className='section projects'>
      <h2 className='section__title'>Projects</h2>

      <div className='projects__tabs'>
        {companies.map((company) => (
          <button
            key={company}
            type='button'
            className={`projects__tab ${company === activeCompany ? 'active' : ''}`}
            onClick={() => setActiveCompany(company)}
          >
            {company}
          </button>
        ))}
      </div>

      <div className='projects__grid'>
        {filteredProjects.map((project) => (
          <div className='project__card' key={uniqid()}>
            <h3 className='project__name'>{project.name}</h3>
            <p className='project__description'>{project.description}</p>
            <ul className='project__stack'>
              {project.stack.map((tech) => (
                <li key={tech} className='project__stack-item'>
                  {tech}
                </li>
              ))}
            </ul>
            {project.sourceCode && (
              <a
                href={project.sourceCode}
                className='link project__link'
                target='_blank'
                rel='noopener noreferrer'
              >
                Source Code
              </a>
            )}
            {project.livePreview && (
              <a
                href={project.livePreview}
                className='link project__link'
                target='_blank'
                rel='noopener noreferrer'
              >
                Live Preview
              </a>
            )}
          </div>
        ))}
      </div>
    </section>
  )
}

export default Projects
